    if isinstance(term, Constant):
        value = int(term.value)
        return lambda matrix: value
    if isinstance(term, SymbolRef):
        if term.name not in positions:
            raise KeyError(f"Unknown symbol reference: {term.name}")
        index = positions[term.name]
        return lambda matrix: matrix[:, index]
    if isinstance(term, BinaryTerm):
        left = compile_term(term.left, positions)
        right = compile_term(term.right, positions)
        if term.op == "+":
            return lambda matrix: left(matrix) + right(matrix)
        if term.op == "-":
            return lambda matrix: left(matrix) - right(matrix)
        if term.op == "*":
            return lambda matrix: left(matrix) * right(matrix)
        if term.op == "/":
            return lambda matrix: left(matrix) // right(matrix)
        raise ValueError(f"Unsupported term op: {term.op}")
    if isinstance(term, FuncCall):
        args = [compile_term(arg, positions) for arg in term.args]
        name = term.name.lower()
        if name == "sum":
            def _sum(matrix):
                values = [arg(matrix) for arg in args]
                total = values[0]
                for extra in values[1:]:
                    total = total + extra
                return total
            return _sum
        if name == "min":
            return lambda matrix: _reduce_columns(args, matrix, np.minimum)
        if name == "max":
            return lambda matrix: _reduce_columns(args, matrix, np.maximum)
        raise ValueError(f"Unsupported function: {term.name}")
    raise TypeError(f"Unsupported term node: {type(term)!r}")


def _reduce_columns(args, matrix, combine):
    current = args[0](matrix)
    for arg in args[1:]:
        current = combine(current, arg(matrix))
    return current


def _compare_columns(op: str, left, right):
    if op == "=":
        return left == right
    if op == "!=":
        return left != right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    raise ValueError(f"Unsupported comparator: {op}")


def compile_formula(formula: Formula, positions: dict[str, int]):
    """Compile a formula AST into ``f(matrix) -> bool ndarray``.

    The compiled predicate is a pure function of the window matrix, so the same
    closure evaluates training windows and every enumerated universe window.
    Scalar results (constant-only comparisons) are broadcast to the row count.
    """
    def run(matrix):
        value = node(matrix)
        if isinstance(value, np.ndarray):
            return value if value.dtype == np.bool_ else value.astype(bool)
        broadcast = np.empty(matrix.shape[0], dtype=bool)
        broadcast[:] = bool(value)
        return broadcast

    def build(node_formula):
        if isinstance(node_formula, BoolConst):
            constant = bool(node_formula.value)
            return lambda matrix: np.full(matrix.shape[0], constant, dtype=bool)
        if isinstance(node_formula, Compare):
            left = compile_term(node_formula.left, positions)
            right = compile_term(node_formula.right, positions)
            op = node_formula.op
            return lambda matrix: _compare_columns(op, left(matrix), right(matrix))
        if isinstance(node_formula, BoolNot):
            inner = build(node_formula.value)
            return lambda matrix: ~inner(matrix)
        if isinstance(node_formula, BoolAnd):
            parts = [build(child) for child in node_formula.values]
            return lambda matrix: _combine_bool(parts, matrix, operator.and_)
        if isinstance(node_formula, BoolOr):
            parts = [build(child) for child in node_formula.values]
            return lambda matrix: _combine_bool(parts, matrix, operator.or_)
        if isinstance(node_formula, Implies):
            left = build(node_formula.left)
            right = build(node_formula.right)
            return lambda matrix: (~left(matrix)) | right(matrix)
        raise ValueError("Quantified formulas must be projected before compilation")

    node = build(formula)
    return run


def _combine_bool(parts, matrix, combine):
    current = parts[0](matrix)
    for part in parts[1:]:
        current = combine(current, part(matrix))
    return current
